function buildTable(lang: LangId): Record<string, string> {
  const groups = raw[lang] ?? []
  const table: Record<string, string> = {}
  keyGroups.forEach((keys, gi) => {
    const parts = (groups[gi] ?? "").split("|")
    keys.forEach((k, ki) => {
      table[k] = parts[ki] ?? ""
    })
  })
  return table
}

const zhTable = buildTable("zh")
const strings: Record<LangId, Record<string, string>> = {} as Record<
  LangId,
  Record<string, string>
>
appLanguages.forEach((lang) => {
  const table = buildTable(lang)
  keyGroups.forEach((keys) => {
    keys.forEach((k) => {
      if (!table[k]) table[k] = zhTable[k] ?? k
    })
  })
  strings[lang] = table
})

const devMode =
  typeof import.meta !== "undefined" &&
  (import.meta as { env?: { DEV?: boolean } }).env?.DEV === true
if (devMode) {
  appLanguages.forEach((lang) => {
    const groups = raw[lang] ?? []
    keyGroups.forEach((keys, gi) => {
      const parts = (groups[gi] ?? "").split("|")
      if (parts.length !== keys.length) {
        console.warn(
          `[i18n] ${lang} group ${gi}: ${parts.length} values, expected ${keys.length}`,
        )
      }
    })
  })
}

export function useT() {
  const [lang] = useAppLanguage()
  const table = strings[lang] ?? strings.zh
  return useCallback(
    (key: string): string => table[key] ?? strings.zh[key] ?? key,
    [table],
  )
}